```c
int R = 3, C = 4;
// Allocate an array of R pointers to int
int **matrix = (int **)malloc(R * sizeof(int *));
if (matrix == NULL) { /* handle allocation error */ }

// For each pointer, allocate an array of C ints
for (int i = 0; i < R; i++) {
    matrix[i] = (int *)malloc(C * sizeof(int));
    if (matrix[i] == NULL) { /* handle error, free previously allocated rows */ }
}

// To free the memory:
for (int i = 0; i < R; i++) {
    free(matrix[i]); // Free each row
}
free(matrix); // Free the array of pointers
```
